987	            // A memo hit copies the tree it recalls, and a conversion can build gigabytes of them between two requests.
988	            crate::heap::step()?;
989	            if let Some(entry) = self.recall(info.id, cx) {
990	                self.state.hits.fetch_add(1, Ordering::Relaxed);
991	                if let Some(frame) = &cx.frame {
992	                    frame.absorb(&entry.asked, &cx.enclosing);
993	                }
994	                return Ok(PropType::clone(&entry.converted));
995	            }
996	            self.state.misses.fetch_add(1, Ordering::Relaxed);
997	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
998	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
999	            let mut converted = self.uncached(info, &own).await?;
1000	            if past_size_budget(&converted, MAX_SIZE) {
1001	                let origin = self.origin(info).await?;
1002	                converted = self.truncated(info, origin.as_ref(), TruncationLimit::Depth).await?;
