1160	    impl Served for Underived {
1161	        fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure> {
1162	            match method {
1163	                "initialize" => Ok("null".to_string()),
1164	                "createSnapshot" => {
1165	                    // As many programs as asked for.
1166	                    let params: Value = serde_json::from_slice(params).unwrap();
1167	                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
1168	                    let projects: Vec<Value> = (0..count).map(|n| json!({ "id": format!("p{n}") })).collect();
1169	                    Ok(json!({ "snapshot": 1, "projects": projects }).to_string())
1170	                }
1171	                "updateSnapshot" if self.panics => panic!("checker invariant broken"),
1172	                "updateSnapshot" => Err(Failure { message: "a file nests too deep".to_string(), panicked: false }),
1173	                "release" => {
1174	                    let params: Value = serde_json::from_slice(params).unwrap();
1175	                    self.released.lock().unwrap().push(params["snapshot"].as_u64().unwrap());
1176	                    Ok("null".to_string())
1177	                }
1178	                other => panic!("unexpected {other}"),
1179	            }
1180	        }
