import json, re, statistics, sys, os

R = sys.argv[1]
ANSI = re.compile(r"\x1b\[[0-9;]*m")


def strip_stats(v):
    if isinstance(v, dict):
        return {k: strip_stats(x) for k, x in v.items() if k != "stats"}
    if isinstance(v, list):
        return [strip_stats(x) for x in v]
    return v


def load(path):
    with open(path) as f:
        return strip_stats(json.load(f))


def degraded(doc):
    text = json.dumps(doc)
    return "checker-fallback" in text or "checker_fallback" in text


def err_facts(path):
    text = ANSI.sub("", open(path, errors="replace").read())
    user = float(re.search(r"([\d.]+) user", text).group(1))
    sys_ = float(re.search(r"([\d.]+) sys", text).group(1))
    real = float(re.search(r"([\d.]+) real", text).group(1))
    rss = int(re.search(r"(\d+)\s+maximum resident set size", text).group(1))
    m = re.search(r"semantic backend finished requests=(\{.*?\})", text)
    reqs = json.loads(m.group(1)) if m else {}
    total = sum(v for k, v in reqs.items() if k not in ("batchRequests", "inBatches"))
    return dict(cpu=user + sys_, real=real, rss=rss / 2**20, requests=total, batches=reqs.get("batchRequests", 0))


for corpus in sys.argv[2:]:
    rows = {"base": [], "new": []}
    ref = None
    for r in range(1, 6):
        for b in ("base", "new"):
            j = f"{R}/{corpus}.{b}.{r}.json"
            if not os.path.exists(j):
                continue
            doc = load(j)
            if ref is None:
                ref = doc
            same = doc == ref
            facts = err_facts(f"{R}/{corpus}.{b}.{r}.err")
            facts["degraded"] = degraded(doc)
            facts["same"] = same
            print(corpus, b, r, facts)
            if not facts["degraded"]:
                rows[b].append(facts)
    for b, fs in rows.items():
        if fs:
            med = {k: statistics.median(f[k] for f in fs) for k in ("cpu", "real", "rss", "requests", "batches")}
            print("MEDIAN", corpus, b, len(fs), {k: round(v, 1) for k, v in med.items()})

