    key: FlightKey,
    flight: Arc<Flight>,
    _done: tokio::sync::watch::Sender<()>,
}

impl Drop for Lead<'_> {
    fn drop(&mut self) {
        let mut table = self.flights.lock();
        if table.running.get(&self.key).is_some_and(|flight| Arc::ptr_eq(flight, &self.flight)) {
            table.running.remove(&self.key);
        }
    }
}

